INSERT INTO public.crm_users(user_id,email,role) SELECT u.id,COALESCE(u.email,''),CASE WHEN EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u.id AND r.role='admin') OR EXISTS(SELECT 1 FROM public.cms_members m WHERE m.user_id=u.id AND m.role='owner') THEN 'admin' ELSE 'sales' END FROM auth.users u WHERE EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u.id AND r.role='admin') OR EXISTS(SELECT 1 FROM public.cms_members m WHERE m.user_id=u.id AND m.role IN ('owner','sales')) ON CONFLICT DO NOTHING;
CREATE FUNCTION public.crm_lead_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.crm_role()='sales' AND TG_OP='INSERT' THEN RAISE EXCEPTION 'Only Admin can create leads'; END IF; IF public.crm_role()='sales' AND TG_OP='UPDATE' AND (NEW.merged_into IS DISTINCT FROM OLD.merged_into OR NEW.first_response_at IS DISTINCT FROM OLD.first_response_at AND pg_trigger_depth()<2) THEN RAISE EXCEPTION 'Protected lead fields'; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_lead_guard BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.crm_lead_guard();
CREATE FUNCTION public.crm_settings_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF jsonb_typeof(NEW.stages)<>'array' OR jsonb_array_length(NEW.stages)<3 OR NOT NEW.stages ?& ARRAY['opportunity','won','lost'] OR (SELECT count(*) FROM jsonb_array_elements_text(NEW.stages))<>(SELECT count(DISTINCT s) FROM jsonb_array_elements_text(NEW.stages) s) THEN RAISE EXCEPTION 'Invalid stages'; END IF; IF EXISTS(SELECT 1 FROM public.deals WHERE NOT NEW.stages ? stage) THEN RAISE EXCEPTION 'Stage is in use'; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_settings_guard BEFORE INSERT OR UPDATE ON public.crm_settings FOR EACH ROW EXECUTE FUNCTION public.crm_settings_guard();
CREATE POLICY crm_restrict_legacy_requests ON public.contact_requests AS RESTRICTIVE FOR ALL TO authenticated USING(public.crm_role()='admin' OR (public.crm_role() IS NULL AND public.cms_access('leads'))) WITH CHECK(public.crm_role()='admin' OR (public.crm_role() IS NULL AND public.cms_access('leads')));
CREATE POLICY crm_restrict_legacy_chats ON public.chat_threads AS RESTRICTIVE FOR SELECT TO authenticated USING(public.crm_role()='admin' OR public.crm_role() IS NULL);
CREATE POLICY crm_restrict_legacy_messages ON public.chat_messages AS RESTRICTIVE FOR SELECT TO authenticated USING(public.crm_role()='admin' OR public.crm_role() IS NULL);